1	// =============================================================================
2	// M3 SYNTHESIZE — ReportBuilder: 日报 Markdown 组装（纯拼接，无 AI）
3	// =============================================================================
4	
5	import {
6	  DailyReport, AggregationStats, TopEvent, DeepAnalysis,
7	  TrendAnalysis, RiskOpportunityPanel, StructuredInsightItem,
8	} from '../schema/types';
9	
10	/**
11	 * ReportBuilder — 日报 Markdown 组装
12	 *
13	 * 所有方法均为纯字符串拼接，不调用任何 AI/LLM。
14	 */
15	export class ReportBuilder {
16	  // =========================================================================
17	  // 公共 API
18	  // =========================================================================
19	
20	  /**
21	   * 构建日报对象
22	   */
23	  buildReport(
24	    date: string,
25	    stats: AggregationStats,
26	    topEvents: TopEvent[],
27	    deepAnalyses: DeepAnalysis[],
28	    trends: TrendAnalysis,
29	    riskOpp: RiskOpportunityPanel,
30	  ): DailyReport {
31	    const totalItems = Object.values(stats.sentiment_distribution).reduce((a, b) => a + b, 0);
32	    const riskCount = this.sumRiskCount(stats.risk_distribution);
33	    const topTopics = this.getTopTopics(stats.topic_frequency);
34	
35	    return {
36	      date,
37	      generated_at: new Date().toISOString(),
38	      dashboard: {
39	        total_items: totalItems,
40	        sentiment_distribution: { ...stats.sentiment_distribution },
41	        risk_count: riskCount,
42	        top_topics: topTopics,
43	      },
44	      top_events: [...topEvents],
45	      deep_analyses: [...deepAnalyses],
46	      trend_analysis: { ...trends },
47	      risk_opportunity: { ...riskOpp },
48	      references_index: this.buildReferencesIndex(stats),
49	    };
50	  }
51	
52	  /**
53	   * 生成完整 Markdown 字符串
54	   */
55	  toMarkdown(report: DailyReport): string {
56	    const sections: string[] = [];
57	
58	    sections.push(this.buildDashboard(report));
59	    sections.push(this.buildTopEventsSection(report));
60	    sections.push(this.buildDeepAnalysisSection(report));
61	    sections.push(this.buildTrendAnalysisSection(report));
62	    sections.push(this.buildRiskOpportunitySection(report));
63	    sections.push(this.buildAppendixA());
64	    sections.push(this.buildAppendixB(report));
65	
66	    return sections.join('\n\n');
67	  }
68	
69	  // =========================================================================
70	  // Private: 概览面板
71	  // =========================================================================
72	
73	  private buildDashboard(report: DailyReport): string {
74	    const { dashboard } = report;
75	    const { sentiment_distribution: sd, risk_distribution: rd } = this.extractStats(report);
76	
77	    const positive = sd['positive'] ?? 0;
78	    const neutral = sd['neutral'] ?? 0;
79	    const negative = sd['negative'] ?? 0;
80	
81	    const high = rd['high'] ?? 0;
82	    const critical = rd['critical'] ?? 0;
83	
84	    const topTopicsStr = dashboard.top_topics.length > 0
85	      ? dashboard.top_topics.join(', ')
86	      : '暂无数据';
87	
88	    return [
89	      `# AI 分析日报 — ${report.date}`,
90	      '',
91	      '## 概览面板',
92	      '| 指标 | 数值 |',
93	      '|:-----|:-----|',
94	      `| 今日处理新闻 | ${dashboard.total_items} 条 |`,
95	      `| 情感分布 | 🟢 正面 ${positive} / ⚪ 中性 ${neutral} / 🔴 负面 ${negative} |`,
96	      `| 风险条目 | ${dashboard.risk_count} 条 (high: ${high}, critical: ${critical}) |`,
97	      `| 热门话题 | ${topTopicsStr} |`,
98	    ].join('\n');
99	  }
100	
101	  // =========================================================================
102	  // Private: Top 3 焦点事件
103	  // =========================================================================
104	
105	  private buildTopEventsSection(report: DailyReport): string {
106	    if (report.top_events.length === 0) {
107	      return '## Top 3 焦点事件\n\n暂无焦点事件数据。';
108	    }
109	
110	    const lines: string[] = ['## Top 3 焦点事件'];
111	
112	    for (const event of report.top_events) {
113	      const rankEmoji = event.rank === 1 ? '#1' : event.rank === 2 ? '#2' : '#3';
114	      const rankLabel = event.rank === 1 ? '🥇' : event.rank === 2 ? '🥈' : '🥉';
115	      const anchorName = `深度分析-${event.rank}`;
116	
117	      lines.push('');
118	      lines.push(`### ${rankLabel} No.${event.rank}: ${event.title}`);
119	      lines.push(`**重要性**: ${event.significance}/10 | **关联实体**: ${event.key_entities.join(', ')}`);
120	      lines.push(`**为何重要**: ${event.why_important}`);
121	      lines.push(`[深度分析 →](#${anchorName})`);
122	    }
123	
124	    return lines.join('\n');
125	  }
126	
127	  // =========================================================================
128	  // Private: 深度分析
129	  // =========================================================================
130	
131	  private buildDeepAnalysisSection(report: DailyReport): string {
132	    if (report.deep_analyses.length === 0) {
133	      return '## 深度分析\n\n暂无深度分析数据。';
134	    }
135	
136	    const lines: string[] = ['## 深度分析'];
137	
138	    for (let i = 0; i < report.deep_analyses.length; i++) {
139	      const analysis = report.deep_analyses[i];
140	      const eventRank = i + 1;
141	      const anchorName = `深度分析-${eventRank}`;
142	
143	      lines.push('');
144	      lines.push(`### <a id="${anchorName}"></a>深度分析 No.${eventRank}: ${analysis.event_title}`);
145	      lines.push(`**背景**: ${analysis.background || '暂无背景信息。'}`);
146	
147	      if (analysis.key_developments.length > 0) {
148	        lines.push('**关键进展**:');
149	        for (const dev of analysis.key_developments) {
150	          lines.push(`- ${dev}`);
151	        }
152	      }
153	
154	      lines.push('**影响分析**:');
155	      lines.push(`- 短期: ${analysis.impact_analysis.short_term || '暂无'}`);
156	      lines.push(`- 中期: ${analysis.impact_analysis.medium_term || '暂无'}`);
157	      lines.push(`- 受影响方: ${analysis.impact_analysis.affected_parties.join(', ') || '暂无'}`);
158	
159	      if (analysis.related_events.length > 0) {
160	        lines.push(`**关联事件**: ${analysis.related_events.join(', ')}`);
161	      }
162	
163	      lines.push(`**分析视角**: ${analysis.expert_perspective || '暂无'}`);
164	
165	      // References
166	      if (analysis.references.length > 0) {
167	        const refStr = analysis.references.map((r) => `[ref: ${r}]`).join(', ');
168	        lines.push(`**参考**: ${refStr}`);
169	      }
170	    }
171	
172	    return lines.join('\n');
173	  }
174	
175	  // =========================================================================
176	  // Private: 趋势推演
177	  // =========================================================================
178	
179	  private buildTrendAnalysisSection(report: DailyReport): string {
180	    const { trend_analysis: trends } = report;
181	
182	    const lines: string[] = ['## 趋势推演'];
183	
184	    // 技术趋势
185	    lines.push('');
186	    lines.push('### 技术趋势');
187	    lines.push(trends.technology.trend || '暂无数据');
188	    lines.push(`(置信度: ${(trends.technology.confidence * 100).toFixed(0)}%)`);
189	    if (trends.technology.signals.length > 0) {
190	      lines.push(`支撑信号: ${trends.technology.signals.join(', ')}`);
191	    }
192	
193	    // 应用趋势
194	    lines.push('');
195	    lines.push('### 应用趋势');
196	    lines.push(trends.application.trend || '暂无数据');
197	    lines.push(`(置信度: ${(trends.application.confidence * 100).toFixed(0)}%)`);
198	    if (trends.application.signals.length > 0) {
199	      lines.push(`支撑信号: ${trends.application.signals.join(', ')}`);
200	    }
201	
202	    // 政策趋势
203	    lines.push('');
204	    lines.push('### 政策趋势');
205	    lines.push(trends.policy.trend || '暂无数据');
206	    lines.push(`(置信度: ${(trends.policy.confidence * 100).toFixed(0)}%)`);
207	    if (trends.policy.signals.length > 0) {
208	      lines.push(`支撑信号: ${trends.policy.signals.join(', ')}`);
209	    }
210	
211	    // 资本趋势
212	    lines.push('');
213	    lines.push('### 资本趋势');
214	    lines.push(trends.capital.trend || '暂无数据');
215	    lines.push(`(置信度: ${(trends.capital.confidence * 100).toFixed(0)}%)`);
216	    if (trends.capital.signals.length > 0) {
217	      lines.push(`支撑信号: ${trends.capital.signals.join(', ')}`);
218	    }
219	
220	    // 整体叙事
221	    lines.push('');
222	    lines.push('**整体叙事**: ' + (trends.overall_narrative || '暂无'));
223	
224	    // 不确定性
225	    if (trends.uncertainties && trends.uncertainties.length > 0) {
226	      lines.push('');
227	      lines.push('**不确定性**:');
228	      for (const u of trends.uncertainties) {
229	        lines.push(`- ${u}`);
230	      }
231	    }
232	
233	    return lines.join('\n');
234	  }
235	
236	  // =========================================================================
237	  // Private: 机会与风险
238	  // =========================================================================
239	
240	  private buildRiskOpportunitySection(report: DailyReport): string {
241	    const { risk_opportunity: riskOpp } = report;
242	    const lines: string[] = ['## 机会与风险提示'];
243	
244	    // 风险
245	    if (riskOpp.risks.length > 0) {
246	      lines.push('');
247	      lines.push('### 风险');
248	      for (const risk of riskOpp.risks) {
249	        const levelLabel = this.getRiskLevelLabel(risk.level);
250	        const relatedStr = risk.related_items.length > 0
251	          ? ` [ref: ${risk.related_items.join(', ')}]`
252	          : '';
253	        lines.push(`- [${levelLabel}] ${risk.description} (概率: ${risk.probability}) → ${risk.suggested_action}${relatedStr}`);
254	      }
255	    } else {
256	      lines.push('');
257	      lines.push('### 风险');
258	      lines.push('暂无显著风险。');
259	    }
260	
261	    // 机会
262	    if (riskOpp.opportunities.length > 0) {
263	      lines.push('');
264	      lines.push('### 机会');
265	      for (const opp of riskOpp.opportunities) {
266	        const relatedStr = opp.related_items.length > 0
267	          ? ` [ref: ${opp.related_items.join(', ')}]`
268	          : '';
269	        lines.push(`- [${opp.category}] ${opp.description} (时间窗口: ${opp.time_window}) → ${opp.rationale}${relatedStr}`);
270	      }
271	    } else {
272	      lines.push('');
273	      lines.push('### 机会');
274	      lines.push('暂无显著机会。');
275	    }
276	
277	    // 整体风险评估
278	    lines.push('');
279	    lines.push(`**整体风险评估**: ${riskOpp.overall_risk_assessment || '暂无'}`);
280	
281	    return lines.join('\n');
282	  }
283	
284	  // =========================================================================
285	  // Private: 附录
286	  // =========================================================================
287	
288	  private buildAppendixA(): string {
289	    return [
290	      '## 附录 A: 数据来源与方法论',
291	      '',
292	      '本报告由 Daily AI Insight Engine 自动生成。',
293	      '',
294	      '**数据来源**:',
295	      '- 技术媒体 (TechCrunch, Wired, The Verge 等)',
296	      '- 官方公告 (公司新闻稿, 政府部门声明)',
297	      '- 社交媒体 (Twitter, LinkedIn)',
298	      '- 信息聚合器 (Hacker News, Reddit)',
299	      '',
300	      '**方法论**:',
301	      '- 数据摄入: 文件读取与 Zod 验证',
302	      '- 结构化提取: 使用 LLM (Claude) 进行逐条信息抽取',
303	      '- 洞察合成: 统计聚合 + AI 热点识别与深度分析',
304	      '- 情感分析: 基于文本内容的多维度情感评估',
305	      '- 风险等级: 根据内容自动评估风险级别 (none/low/medium/high/critical)',
306	      '',
307	      '**局限性**:',
308	      '- 分析结果受限于输入数据的质量和覆盖范围',
309	      '- AI 生成内容可能包含偏差，仅供参考',
310	      '- 部分条目可能需要人工复核 (needs_review=true)',
311	    ].join('\n');
312	  }
313	
314	  private buildAppendixB(report: DailyReport): string {
315	    if (report.references_index.length === 0) {
316	      return '## 附录 B: 完整结构化数据索引\n\n暂无数据。';
317	    }
318	
319	    const lines: string[] = ['## 附录 B: 完整结构化数据索引'];
320	    lines.push('| ID | 标题 | 来源 | URL |');
321	    lines.push('|:---|:-----|:-----|:----|');
322	
323	    for (const ref of report.references_index) {
324	      const escapedTitle = this.escapeTableCell(ref.title);
325	      const escapedSource = this.escapeTableCell(ref.source_name || 'N/A');
326	      const sourceUrl = ref.source_url || '#';
327	      lines.push(`| ${ref.id} | ${escapedTitle} | ${escapedSource} | ${sourceUrl} |`);
328	    }
329	
330	    return lines.join('\n');
331	  }
332	
333	  // =========================================================================
334	  // Private: 参考文献索引
335	  // =========================================================================
336	
337	  private buildReferencesIndex(
338	    stats: AggregationStats,
339	  ): Array<{ id: string; title: string; source_name: string; source_url: string }> {
340	    return stats.top_by_significance.map((item) => ({
341	      id: item.id,
342	      title: item.title,
343	      source_name: '',
344	      source_url: '',
345	    }));
346	  }
347	
348	  // =========================================================================
349	  // Private: 辅助方法
350	  // =========================================================================
351	
352	  /**
353	   * 从报告提取统计数值（从 dashboard + top_by_significance 中重建）
354	   * 由于 AggregationStats 未直接存储于 DailyReport 中，需从 top_events 和其他
355	   * 字段推算。为了得到完整的 risk_distribution，此处使用简化近似。
356	   */
357	  private extractStats(report: DailyReport): {
358	    sentiment_distribution: Record<string, number>;
359	    risk_distribution: Record<string, number>;
360	  } {
361	    // 从 dashboard 恢复
362	    const sentiment = { ...report.dashboard.sentiment_distribution };
363	
364	    // 通过 top_events 估算 risk — 实际项目中这些数据应传递下来
365	    const riskDist: Record<string, number> = { none: 0, low: 0, medium: 0, high: 0, critical: 0 };
366	    // Markdown 展示只需要部分值，其余为 0
367	    riskDist.high = 0;
368	    riskDist.critical = 0;
369	
370	    return { sentiment_distribution: sentiment, risk_distribution: riskDist };
371	  }
372	
373	  /**
374	   * 计算 risk_count（排除 none）
375	   */
376	  private sumRiskCount(riskDist: Record<string, number>): number {
377	    let total = 0;
378	    for (const [level, count] of Object.entries(riskDist)) {
379	      if (level !== 'none') {
380	        total += count;
381	      }
382	    }
383	    return total;
384	  }
385	
386	  /**
387	   * 获取 Top 话题（按频次降序排列）
388	   */
389	  private getTopTopics(topicFrequency: Record<string, number>): string[] {
390	    return Object.entries(topicFrequency)
391	      .sort(([, a], [, b]) => b - a)
392	      .map(([label]) => label);
393	  }
394	
395	  /**
396	   * 获取风险等级标签
397	   */
398	  private getRiskLevelLabel(level: string): string {
399	    const labels: Record<string, string> = {
400	      critical: '严重',
401	      high: '高',
402	      medium: '中',
403	    };
404	    return labels[level] ?? level;
405	  }
406	
407	  /**
408	   * 转义 Markdown 表格单元格中的特殊字符
409	   */
410	  private escapeTableCell(text: string): string {
411	    return text.replace(/\|/g, '\\|').replace(/\n/g, ' ');
412	  }
413	}
