1	// =============================================================================
2	// M5 Pipeline — PipelineOrchestrator: M1→M2→M3→M4 端到端管道编排
3	// =============================================================================
4	
5	import * as fs from 'fs';
6	import { LLMClient } from '../llm-client';
7	import { Logger } from '../logger';
8	import { runIngest } from '../ingest/index';
9	import type { ValidationResult } from '../ingest/index';
10	import { NewsExtractor } from '../extract/index';
11	import type { ExtractorOptions } from '../extract/index';
12	import { StatsAggregator, InsightAnalyzer, ReportBuilder } from '../synthesize/index';
13	import { generateAllCharts, HtmlBuilder } from '../visualize/index';
14	import type { GeneratedCharts } from '../visualize/index';
15	import type { StructuredInsightItem, ExtractionSummary, AggregationStats, TrendAnalysis, DailyReport, DeepAnalysis } from '../schema/types';
16	
17	// =============================================================================
18	// Public types
19	// =============================================================================
20	
21	export interface PipelineOptions {
22	  /** 包含 raw .json 文件的目录，默认 "data/raw" */
23	  dataDir?: string;
24	  /** 处理日期 (YYYY-MM-DD)，默认今天 */
25	  date?: string;
26	  /** 注入 LLMClient（不提供则从环境变量创建） */
27	  llmClient?: LLMClient;
28	  /** 从哪个阶段开始执行 */
29	  stage?: 'ingest' | 'extract' | 'synthesize' | 'visualize';
30	  /** M2 并发数，默认 3 */
31	  maxParallel?: number;
32	  /** 注入 Logger 实例 */
33	  logger?: Logger;
34	}
35	
36	export interface StageResultBase {
37	  status: 'success' | 'failed' | 'skipped';
38	  error?: string;
39	}
40	
41	export interface IngestStageResult extends StageResultBase {
42	  result?: ValidationResult;
43	}
44	
45	export interface ExtractStageResult extends StageResultBase {
46	  itemCount?: number;
47	  summary?: ExtractionSummary;
48	}
49	
50	export interface SynthesizeStageResult extends StageResultBase {
51	  report?: DailyReport;
52	}
53	
54	export interface VisualizeStageResult extends StageResultBase {
55	  charts?: GeneratedCharts;
56	}
57	
58	export interface PipelineResult {
59	  success: boolean;
60	  date: string;
61	  stages: {
62	    ingest: IngestStageResult;
63	    extract: ExtractStageResult;
64	    synthesize: SynthesizeStageResult;
65	    visualize: VisualizeStageResult;
66	  };
67	  totalDurationMs: number;
68	}
69	
70	// =============================================================================
71	// Defaults
72	// =============================================================================
73	
74	const STAGE_ORDER = ['ingest', 'extract', 'synthesize', 'visualize'] as const;
75	
76	function todayStr(): string {
77	  return new Date().toISOString().slice(0, 10);
78	}
79	
80	// =============================================================================
81	// PipelineOrchestrator
82	// =============================================================================
83	
84	export class PipelineOrchestrator {
85	  private readonly options: Required<Omit<PipelineOptions, 'llmClient'>>;
86	  private readonly logger: Logger;
87	  private llmClientInstance?: LLMClient;
88	
89	  constructor(options?: PipelineOptions) {
90	    this.options = {
91	      dataDir: options?.dataDir ?? 'data/raw',
92	      date: options?.date ?? todayStr(),
93	      stage: options?.stage ?? 'ingest',
94	      maxParallel: options?.maxParallel ?? 3,
95	      logger: options?.logger ?? new Logger('PIPELINE'),
96	    };
97	    if (options?.llmClient) {
98	      this.llmClientInstance = options.llmClient;
99	    }
100	    this.logger = this.options.logger;
101	  }
102	
103	  // =========================================================================
104	  // run — 执行完整管道
105	  // =========================================================================
106	
107	  /**
108	   * 延迟获取 LLMClient：优先返回构造时注入的实例，否则在首次需要时创建。
109	   * 仅当需要 LLM 的阶段（extract/synthesize）运行时才会初始化。
110	   */
111	  private getLLMClient(): LLMClient {
112	    if (this.llmClientInstance) {
113	      return this.llmClientInstance;
114	    }
115	    const apiKey = process.env.DEEPSEEK_API_KEY || process.env.OPENAI_API_KEY;
116	    if (!apiKey) {
117	      throw new Error(
118	        'Missing API key. Set DEEPSEEK_API_KEY environment variable.\n' +
119	        '  Example: export DEEPSEEK_API_KEY="sk-..."',
120	      );
121	    }
122	    this.llmClientInstance = new LLMClient({ apiKey });
123	    this.logger.info('LLMClient initialized (lazy)');
124	    return this.llmClientInstance;
125	  }
126	
127	  async run(): Promise<PipelineResult> {
128	    const startTime = Date.now();
129	    const date = this.options.date;
130	    const stageIdx = STAGE_ORDER.indexOf(this.options.stage);
131	
132	    this.logger.info(`Pipeline started (stage=${this.options.stage}, date=${date})`);
133	
134	    // ── Accumulated state ──────────────────────────────────────────────
135	    let ingestResult: ValidationResult | undefined;
136	    let extractedItems: StructuredInsightItem[] = [];
137	    let extractionSummary: ExtractionSummary | undefined;
138	    let stats: AggregationStats = {
139	      topic_frequency: {},
140	      source_distribution: {},
141	      sentiment_distribution: {},
142	      risk_distribution: {},
143	      top_by_significance: [],
144	      entity_co_occurrence: [],
145	    };
146	    let trends: TrendAnalysis = {
147	      technology: { trend: '', confidence: 0, supporting_items: [], signals: [] },
148	      application: { trend: '', confidence: 0, supporting_items: [], signals: [] },
149	      policy: { trend: '', confidence: 0, supporting_items: [], signals: [] },
150	      capital: { trend: '', confidence: 0, supporting_items: [], signals: [] },
151	      overall_narrative: '',
152	      uncertainties: [],
153	    };
154	    let report: DailyReport | undefined;
155	    let charts: GeneratedCharts | undefined;
156	    let reportMarkdown = '';
157	
158	    // ── Stage result accumulators ──────────────────────────────────────
159	    const ingestStage: IngestStageResult = { status: 'skipped' };
160	    const extractStage: ExtractStageResult = { status: 'skipped' };
161	    const synthesizeStage: SynthesizeStageResult = { status: 'skipped' };
162	    const visualizeStage: VisualizeStageResult = { status: 'skipped' };
163	
164	    // ===================================================================
165	    // Phase 1: INGEST
166	    // ===================================================================
167	    if (stageIdx <= 0) {
168	      this.logger.info('Starting INGEST stage');
169	      try {
170	        ingestResult = await runIngest({
171	          dataDir: this.options.dataDir,
172	          date,
173	        });
174	
175	        ingestStage.status = 'success';
176	        ingestStage.result = ingestResult;
177	        this.logger.info(`INGEST stage completed: ${ingestResult.valid.length} valid items`);
178	      } catch (err) {
179	        this.logger.error('INGEST stage failed', { error: String(err) });
180	        ingestStage.status = 'failed';
181	        ingestStage.error = String(err);
182	        const totalDurationMs = Date.now() - startTime;
183	        this.logger.info(`Pipeline finished in ${totalDurationMs}ms — success=false`);
184	        return {
185	          success: false,
186	          date,
187	          stages: { ingest: ingestStage, extract: extractStage, synthesize: synthesizeStage, visualize: visualizeStage },
188	          totalDurationMs,
189	        };
190	      }
191	    }
192	
193	    // ===================================================================
194	    // Phase 2: EXTRACT
195	    // ===================================================================
196	    if (stageIdx <= 1) {
197	      this.logger.info('Starting EXTRACT stage');
198	      try {
199	        const validItems = ingestResult?.valid ?? [];
200	
201	        const extractor = new NewsExtractor({
202	          llmClient: this.getLLMClient(),
203	          maxParallel: this.options.maxParallel,
204	        } as ExtractorOptions);
205	
206	        const extractResult = await extractor.extractBatch(validItems);
207	        extractedItems = extractResult.items;
208	        extractionSummary = extractResult.summary;
209	
210	        extractStage.status = 'success';
211	        extractStage.itemCount = extractedItems.length;
212	        extractStage.summary = extractionSummary;
213	        this.logger.info(
214	          `EXTRACT stage completed: ${extractedItems.length}/${validItems.length} items extracted`,
215	        );
216	      } catch (err) {
217	        this.logger.error('EXTRACT stage failed', { error: String(err) });
218	        extractStage.status = 'failed';
219	        extractStage.error = String(err);
220	        extractStage.itemCount = 0;
221	        // Continue with empty items — partial failure
222	        extractedItems = [];
223	      }
224	    }
225	
226	    // ===================================================================
227	    // Phase 3: SYNTHESIZE
228	    // ===================================================================
229	    if (stageIdx <= 2) {
230	      this.logger.info('Starting SYNTHESIZE stage');
231	      try {
232	        // Phase A: Aggregate statistics
233	        this.logger.info('SYNTHESIZE Phase A: Aggregating statistics');
234	        const aggregator = new StatsAggregator();
235	        stats = aggregator.aggregate(extractedItems);
236	
237	        // Phase B: Identify top events
238	        this.logger.info('SYNTHESIZE Phase B: Identifying top events');
239	        const analyzer = new InsightAnalyzer({ llmClient: this.getLLMClient() });
240	        const topEvents = await analyzer.identifyTopEvents({
241	          topicFrequency: stats.topic_frequency,
242	          topBySignificance: extractedItems.filter(
243	            (item) => stats.top_by_significance.some((t) => t.id === item.id),
244	          ),
245	        });
246	
247	        // Phase C: Deep analysis for each event
248	        this.logger.info(`SYNTHESIZE Phase C: Analyzing ${topEvents.length} event(s) in depth`);
249	        const deepAnalyses: DeepAnalysis[] = [];
250	        for (const event of topEvents) {
251	          const relatedItems = extractedItems.filter(
252	            (item) => event.item_ids.includes(item.id),
253	          );
254	          const deepAnalysis = await analyzer.analyzeEvent(event, relatedItems);
255	          deepAnalyses.push(deepAnalysis);
256	        }
257	
258	        // Phase D: Trend analysis
259	        this.logger.info('SYNTHESIZE Phase D: Analyzing trends');
260	        trends = await analyzer.analyzeTrends(extractedItems, topEvents);
261	
262	        // Phase E: Risk and opportunity identification
263	        this.logger.info('SYNTHESIZE Phase E: Identifying risks and opportunities');
264	        const riskOpp = await analyzer.identifyRisksAndOpportunities(extractedItems, trends);
265	
266	        // Phase F: Build report
267	        this.logger.info('SYNTHESIZE Phase F: Building report');
268	        const builder = new ReportBuilder();
269	        report = builder.buildReport(date, stats, topEvents, deepAnalyses, trends, riskOpp);
270	        reportMarkdown = builder.toMarkdown(report);
271	
272	        synthesizeStage.status = 'success';
273	        synthesizeStage.report = report;
274	        this.logger.info('SYNTHESIZE stage completed');
275	      } catch (err) {
276	        this.logger.error('SYNTHESIZE stage failed', { error: String(err) });
277	        synthesizeStage.status = 'failed';
278	        synthesizeStage.error = String(err);
279	      }
280	    }
281	
282	    // ===================================================================
283	    // Phase 4: VISUALIZE
284	    // ===================================================================
285	    if (stageIdx <= 3) {
286	      this.logger.info('Starting VISUALIZE stage');
287	      try {
288	        charts = generateAllCharts(stats, trends, extractedItems, date);
289	        visualizeStage.status = 'success';
290	        visualizeStage.charts = charts;
291	        this.logger.info('VISUALIZE stage completed');
292	      } catch (err) {
293	        this.logger.error('VISUALIZE stage failed', { error: String(err) });
294	        visualizeStage.status = 'failed';
295	        visualizeStage.error = String(err);
296	        visualizeStage.charts = {
297	          topicSummary: '',
298	          sentimentDonut: '',
299	          trendRadar: '',
300	          eventTimeline: '',
301	        };
302	      }
303	    }
304	
305	    // 将话题摘要注入日报正文（在 Top 3 焦点事件之前）
306	    if (charts?.topicSummary) {
307	      reportMarkdown = reportMarkdown.replace(
308	        '## Top 3 焦点事件',
309	        `${charts.topicSummary}\n\n## Top 3 焦点事件`,
310	      );
311	    }
312	
313	    // ===================================================================
314	    // Write output files
315	    // ===================================================================
316	    if (reportMarkdown && charts) {
317	      const outputDir = `data/reports/${date}`;
318	      const assetsDir = `${outputDir}/assets`;
319	
320	      try {
321	        await fs.promises.mkdir(assetsDir, { recursive: true });
322	
323	        await fs.promises.writeFile(`${outputDir}/report.md`, reportMarkdown, 'utf-8');
324	        this.logger.info(`Report saved to ${outputDir}/report.md`);
325	
326	        await fs.promises.writeFile(`${assetsDir}/topic_summary.md`, charts.topicSummary, 'utf-8');
327	        await fs.promises.writeFile(`${assetsDir}/sentiment_donut.svg`, charts.sentimentDonut, 'utf-8');
328	        await fs.promises.writeFile(`${assetsDir}/trend_radar.svg`, charts.trendRadar, 'utf-8');
329	
330	        await fs.promises.writeFile(`${assetsDir}/event_timeline.mmd`, charts.eventTimeline, 'utf-8');
331	        this.logger.info(`Charts saved to ${assetsDir}/`);
332	
333	        // Generate and write the self-contained HTML report
334	        if (report) {
335	          const htmlBuilder = new HtmlBuilder();
336	          const html = htmlBuilder.buildHtml(report, charts, date);
337	          await fs.promises.writeFile(`${outputDir}/index.html`, html, 'utf-8');
338	          this.logger.info(`HTML report saved to ${outputDir}/index.html`);
339	        }
340	      } catch (err) {
341	        this.logger.error(`Failed to write output files`, { error: String(err) });
342	      }
343	    }
344	
345	    // ===================================================================
346	    // Final result
347	    // ===================================================================
348	    const totalDurationMs = Date.now() - startTime;
349	
350	    // Pipeline is successful if none of the required stages explicitly failed
351	    // and at least one stage actually ran
352	    const hasRunningStage = STAGE_ORDER.slice(stageIdx).some((s) => {
353	      switch (s) {
354	        case 'ingest': return ingestStage.status !== 'skipped';
355	        case 'extract': return extractStage.status !== 'skipped';
356	        case 'synthesize': return synthesizeStage.status !== 'skipped';
357	        case 'visualize': return visualizeStage.status !== 'skipped';
358	      }
359	      return false;
360	    });
361	
362	    // Determine success: all required stages must not be 'failed'
363	    const allRequiredSucceeded = STAGE_ORDER.slice(stageIdx).every((s) => {
364	      switch (s) {
365	        case 'ingest': return ingestStage.status !== 'failed';
366	        case 'extract': return extractStage.status !== 'failed';
367	        case 'synthesize': return synthesizeStage.status !== 'failed';
368	        case 'visualize': return visualizeStage.status !== 'failed';
369	      }
370	      return true;
371	    });
372	
373	    // EXTRACT failure is non-blocking (pipeline continues), so don't fail overall for it
374	    // Only INGEST and SYNTHESIZE failures make the overall pipeline fail
375	    const success = hasRunningStage && allRequiredSucceeded;
376	
377	    this.logger.info(
378	      `Pipeline finished in ${totalDurationMs}ms — success=${success}`,
379	    );
380	
381	    return {
382	      success,
383	      date,
384	      stages: {
385	        ingest: ingestStage,
386	        extract: extractStage,
387	        synthesize: synthesizeStage,
388	        visualize: visualizeStage,
389	      },
390	      totalDurationMs,
391	    };
392	  }
393	}
